using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text;

namespace NoR.Archipelago
{
    /// <summary>Location key / item code &lt;-&gt; Archipelago id (data/runtime/ap_map.tsv, generated by NoR.ApWorldGen).</summary>
    public sealed class ApMap
    {
        public readonly Dictionary<string, long> LocationId = new Dictionary<string, long>();
        public readonly Dictionary<long, string> LocationKey = new Dictionary<long, string>();
        public readonly Dictionary<long, string> LocationName = new Dictionary<long, string>();
        public readonly Dictionary<long, string> ItemCode = new Dictionary<long, string>();
        public readonly Dictionary<long, string> ItemName = new Dictionary<long, string>();

        public static ApMap LoadEmbedded()
        {
            var m = new ApMap();
            using (var s = typeof(ApMap).Assembly.GetManifestResourceStream("NoR.Archipelago.ap_map.tsv"))
            using (var r = new StreamReader(s, Encoding.UTF8))
            {
                string line;
                while ((line = r.ReadLine()) != null)
                {
                    if (line.Length == 0 || line[0] == '#') continue;
                    var c = line.Split('\t');
                    if (c.Length < 4) continue;
                    long id = long.Parse(c[2], CultureInfo.InvariantCulture);
                    if (c[0] == "L")
                    {
                        m.LocationId[c[1]] = id;
                        m.LocationKey[id] = c[1];
                        m.LocationName[id] = c[3];
                    }
                    else if (c[0] == "I")
                    {
                        m.ItemCode[id] = c[1];
                        m.ItemName[id] = c[3];
                    }
                }
            }
            return m;
        }
    }
}
